//! Generated by tools/gen-mechanics-observer.py. Host-only persistent damage state.
use crate::{Ctx,H,NONE};
use crate::game::character::CharacterState;
use crate::game::composites::LIGAMENT;
use crate::physics_observer as physics;
use hw_real::Real;
use std::fmt::Write;
fn joint<R:Real>(s:&mut String,p:&str,ctx:&Ctx<R>,h:H) {
    write!(s,"{p}present={};",(h!=NONE) as u32).unwrap();
    if h!=NONE {physics::observe_joint(s,p,ctx.world.joint(h));}
}
fn actor<R:Real>(s:&mut String,p:&str,ctx:&Ctx<R>,o:&CharacterState<R>) {
    write!(s,"{p}spine={};{p}intestine={};{p}composite_count={};",if o.spine==NONE {-1} else {o.spine as i32},if o.intestine==NONE {-1} else {o.intestine as i32},o.composite_count).unwrap();
    for i in 0..o.composite_count {
        let c=&o.composites[i as usize];let p=format!("{p}composites[{i}].");
        write!(s,"{p}kind={};",c.kind).unwrap();
        joint(s,&format!("{p}ends[0]."),ctx,c.ends[0]);
        if c.kind==LIGAMENT {
            let [hi,lo]=c.scale.to_words();write!(s,"{p}scale={hi:08x}{lo:08x};").unwrap();
            physics::observe_body(s,&format!("{p}upper."),ctx.world.body(c.upper));
        } else {joint(s,&format!("{p}ends[1]."),ctx,c.ends[1]);}
    }
}
pub fn mechanics_string<R:Real>(ctx:&Ctx<R>)->String {
    let mut s=String::new();
    for (name,value) in [("x",ctx.world.report_cr_normal.x),("y",ctx.world.report_cr_normal.y)] {
        let [hi,lo]=value.to_words();write!(s,"report_normal.{name}={hi:08x}{lo:08x};").unwrap();
    }
    actor(&mut s,"character.",ctx,&ctx.character.primary);
    if ctx.character.primary.kind==3 {actor(&mut s,"child.",ctx,&ctx.character.child);}
    s
}
